/// Status: Show whether the Mac's KVM and its sitter are reachable and what they see.
@MainActor
public enum StatusAction {
    public static let id = "status"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (StatusInput) async throws -> StatusOutput)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (StatusInput, Result<StatusOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: StatusInput) async throws -> StatusOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct StatusIntent: AppIntent {
    public static let title: LocalizedStringResource = "Status"
    public static let description = IntentDescription("Show whether the Mac's KVM and its sitter are reachable and what they see.")

    public init() {}

    public init(_ input: StatusInput) {
        self.init()
    }

    public var input: StatusInput {
        StatusInput()
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<StatusOutput, any Error>
        do { result = .success(try await StatusAction.run(input)) } catch { result = .failure(error) }
        if let dialog = StatusAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

/// The control for status: Button(_:intent:), the same intent Siri and Shortcuts run.
@available(iOS 17.0, macOS 14.0, watchOS 10.0, tvOS 17.0, *)
public struct StatusButton<Label: View>: View {
    public let input: StatusInput
    let label: Label

    public init(_ input: StatusInput, @ViewBuilder label: () -> Label) {
        self.input = input
        self.label = label()
    }

    public var body: some View {
        Button(intent: StatusIntent(input)) { label }
            .accessibilityHint(Text(verbatim: "Show whether the Mac's KVM and its sitter are reachable and what they see."))
    }
}

@available(iOS 17.0, macOS 14.0, watchOS 10.0, tvOS 17.0, *)
extension StatusButton where Label == Text {
    public init(_ input: StatusInput) {
        self.init(input) { Text(verbatim: "Status") }
    }
}

